from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urlsplit, unquote
class Links(HTMLParser):
 def __init__(self): super().__init__();self.ids=set();self.links=[]
 def handle_starttag(self,tag,attrs):
  a=dict(attrs)
  if 'id' in a:self.ids.add(a['id'])
  if tag=='a' and 'href' in a:self.links.append(a['href'])
pages={}
for p in Path('rendered').glob('*.html'):
 parser=Links();parser.feed(p.read_text());pages[p.resolve()]=parser
bad=[];checked=0
for p,parser in pages.items():
 for href in parser.links:
  u=urlsplit(href)
  if u.scheme or u.netloc:continue
  dest=(p.parent/unquote(u.path)).resolve() if u.path else p
  if dest in pages:
   checked+=1
   if u.fragment and unquote(u.fragment) not in pages[dest].ids:bad.append((p.name,href))
  elif u.path.endswith('.html'):bad.append((p.name,href))
print('manifest entries',len(Path('SHA256SUMS').read_text().splitlines()))
print('HTML internal links checked',checked,'bad HTML destinations/fragments',bad)
print('Chapter 10 named test present',Path('tests/test_physical_models_stdlib.py').exists())
PY"

